{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "type": "object",
    "title": "Signal subscription configuration",
    "properties": {
        "name": {
            "propertyOrder": 10,
            "title": "Name",
            "type": "string"
        },
        "signalClass": {
            "propertyOrder": 35,
            "title": "Signal class",
            "type": "string"
        },
        "signalSubclass": {
            "propertyOrder": 36,
            "title": "Signal subclass",
            "type": "string"
        },
        "level": {
            "propertyOrder": 38,
            "title": "Signal level",
            "type": "string",
            "enum": [
                "Very low",
                "Low",
                "Medium",
                "High",
                "Very high",
                "Maximum"
            ]
        },
        "conflate": {
            "propertyOrder": 50,
            "title": "Conflate",
            "default": true,
            "type": "boolean"
        },
        "autoClose": {
            "propertyOrder": 60,
            "title": "Auto-close (sec)",
            "default": 3,
            "type": "number"
        }
    },
    "additionalProperties": false
}

